/// <summary>
/// The <c>AVAWHSContainerContentsControllerCls_Extension</c> represents a extension of WHSContainerContentsController table.
/// </summary>
/// <remarks>
/// AVA_7360_8266_ContainerPrint
/// </remarks>
[
    ExtensionOf(classStr(WHSContainerContentsController))
]
final class AVAWHSContainerContentsControllerCls_Extension
{
}

Method.Source:
/// <summary>
/// CoC for loadPrintManagement
/// </summary>
protected void loadPrintManagement()
{
    next loadPrintManagement();

    this.addCloseContainerProfilePrint();
}

private boolean avaHasProfilSettingDetail()
{
    boolean                     printReport;
    WHSContainerTable           containerTable;
    WHSCloseContainerProfile    closeContainerProfile;

    if (this.parmArgs().record().TableId == tableNum(WHSContainerTable))
    {
        containerTable = this.parmArgs().record();

        if (containerTable)
        {
            closeContainerProfile = WHSCloseContainerProfile::find(containerTable.CloseContainerProfileId);

            if (closeContainerProfile
             && closeContainerProfile.PrintContainerContents == NoYes::Yes)
            {
                printReport = true;
            }
        }
    }

    return printReport;
}

private PrintMgmtPrintSettingDetail avaGetProfilSettingDetail()
{
    WHSContainerTable           containerTable;
    WHSCloseContainerProfile    closeContainerProfile;
    PrintMgmtPrintSettingDetail printSettingDetail;
    SRSPrintDestinationSettings profilSettingDetail;
    PrintMgmtReportFormat       printMgmtReportFormat = PrintMgmtReportFormat::findSystem(printMgmtReportRun.parmDocType());

    if (this.parmArgs().record().TableId == tableNum(WHSContainerTable))
    {
        containerTable = this.parmArgs().record();

        if (containerTable)
        {
            closeContainerProfile = WHSCloseContainerProfile::find(containerTable.CloseContainerProfileId);

            if (closeContainerProfile
             && closeContainerProfile.PrintContainerContents == NoYes::Yes)
            {
                profilSettingDetail = closeContainerProfile.avaGetPrinterSettings();
            }
        }
    }

    if (profilSettingDetail)
    {
        printSettingDetail = new PrintMgmtPrintSettingDetail();

        printSettingDetail.parmReportFormatName(printMgmtReportFormat.Name);
        printSettingDetail.parmType(PrintMgmtDocInstanceType::Copy);
        printSettingDetail.parmNumberOfCopies(1);
        printSettingDetail.parmPrintJobSettings(profilSettingDetail);
    }

    return printSettingDetail;
}
